Think: Create the AWK source file src/date-format.awk inside the workspace implementing parsing, normalization, token mapping and output logic.

Act: bash

```bash
cat > date-format/src/date-format.awk <<'EOF'
# AWK date-format core (expects to be invoked as: awk -f date-format.awk DATE FORMAT)
BEGIN{
  if(ARGC < 3){
    print "Usage: date-format DATE FORMAT" > "/dev/stderr"
    exit 2
  }
  date = ARGV[1]
  fmt  = ARGV[2]
  # prevent AWK from treating the args as files to read
  ARGV[1] = ""; ARGV[2] = ""

  # Try YYYY[-/.\s]M[-/.\s]D or YYYY M D
  if (match(date, /^([0-9]{4})[^0-9]*([0-9]{1,2})[^0-9]*([0-9]{1,2})$/, a)) {
    year = a[1]; mon = a[2]; day = a[3];
  }
  # Try M/D/YYYY or D-M-YYYY (decide month/day by value)
  else if (match(date, /^([0-9]{1,2})[^0-9]*([0-9]{1,2})[^0-9]*([0-9]{4})$/, a)) {
    # if first part looks like a month (1-12) prefer month-first; otherwise day-first
    if ((a[1] + 0) >= 1 && (a[1] + 0) <= 12) {
      mon = a[1]; day = a[2]; year = a[3]
    } else {
      day = a[1]; mon = a[2]; year = a[3]
    }
  } else {
    print "Unrecognized date format: " date > "/dev/stderr"
    exit 3
  }

  # Normalize numeric values and zero-pad month/day
  monn = sprintf("%02d", mon + 0)
  dayn = sprintf("%02d", day + 0)
  Y = year

  result = fmt
  # Replace tokens. Order: longer tokens first (if any) - here only %Y, %m, %d, and %%
  gsub(/%Y/, Y, result)
  gsub(/%m/, monn, result)
  gsub(/%d/, dayn, result)
  gsub(/%%/, "%", result)

  print result
  exit 0
}
EOF
```

