Think: Parse raw_cpu_data.txt to extract CPU counts and model info, flag inconsistencies, and write normalized report to cpu_check_workspace/cpu_report_preparation.txt.

Act: bash

```bash
awk '
BEGIN{lscpu_cpus="-";in_proc=0;proc_count=0}
{
 if ($0 ~ /^--- \/proc\/cpuinfo ---/) { in_proc=1; next }
 if (!in_proc) {
   if ($0 ~ /^[[:space:]]*CPU\\(s\\):/) { lscpu_cpus = $NF }
   if ($0 ~ /^[[:space:]]*Socket\\(s\\):/) sockets = $NF
   if ($0 ~ /^[[:space:]]*Core\\(s\\) per socket:/) cores_per_socket = $NF
   if ($0 ~ /^[[:space:]]*Thread\\(s\\) per core:/) threads_per_core = $NF
 }
 if (in_proc) {
   if ($0 ~ /^[[:space:]]*processor[[:space:]]*:/) { proc_count++ }
   if ($0 ~ /^[[:space:]]*model name[[:space:]]*:/) {
     sub(/^[[:space:]]*model name[[:space:]]*:[[:space:]]*/, "", $0);
     models[$0]=1;
   }
 }
}
END{
 print "Logical_CPUs: " proc_count;
 print "Lscpu_reported_CPUs: " lscpu_cpus;
 if (sockets!="") print "Sockets: " sockets;
 if (cores_per_socket!="") print "Cores_per_socket: " cores_per_socket;
 if (threads_per_core!="") print "Threads_per_core: " threads_per_core;
 print "Distinct_model_names_count: " length(models);
 if (length(models)>0) {
   print "Distinct_model_names:";
   for (m in models) print " - " m;
 }
 if (lscpu_cpus != "-" && lscpu_cpus != "" && proc_count != lscpu_cpus) print "INCONSISTENCY: lscpu reported CPU count differs from /proc/cpuinfo";
 else print "CONSISTENCY: CPU counts OK or lscpu info not found";
 print "READY_FOR_FINAL_EXTRACT: yes";
}
' cpu_check_workspace/raw_cpu_data.txt > cpu_check_workspace/cpu_report_preparation.txt
